// Email Classifier
// Determines routing based on content and sender

const email = $input.first().json;

const subject = (email.subject || '').toLowerCase();
const body = (email.snippet || email.text || '').toLowerCase();
const fromEmail = email.from?.email || email.from || '';
const fromName = email.from?.name || '';
const content = subject + ' ' + body;

// Spam/archive patterns
const spamPatterns = [
  'unsubscribe', 'opt-out', 'opt out', 'remove me',
  'viagra', 'casino', 'lottery', 'winner',
  'nigerian prince', 'inheritance', 'bitcoin opportunity',
  'click here now', 'act now', 'limited time',
  'no-reply', 'noreply', 'donotreply'
];

// Sales patterns (new prospects)
const salesPatterns = [
  'pricing', 'price', 'cost', 'quote', 'how much',
  'interested in', 'looking for', 'need help with',
  'services', 'consultation', 'discovery call',
  'ai audit', 'ai consulting', 'want to learn more'
];

// Support patterns (existing clients)
const supportPatterns = [
  'help', 'issue', 'problem', 'broken', 'not working',
  'error', 'bug', 'down', 'crashed', 'fix',
  'urgent', 'emergency', 'asap'
];

// Maintenance patterns
const maintenancePatterns = [
  'update', 'change', 'edit', 'modify', 'maintenance',
  'add to website', 'website change', 'new page',
  'update my site', 'change the'
];

// Partnership patterns
const partnershipPatterns = [
  'partnership', 'partner', 'collaborate', 'collaboration',
  'media', 'press', 'interview', 'podcast', 'feature',
  'guest', 'speaking', 'conference'
];

// Check patterns
let classification = 'unknown';
let confidence = 0;
let destination = 'review';

// Check spam first
for (const pattern of spamPatterns) {
  if (content.includes(pattern)) {
    classification = 'spam';
    confidence = 0.9;
    destination = 'archive';
    break;
  }
}

// Check partnership (flag for owner)
if (classification === 'unknown') {
  for (const pattern of partnershipPatterns) {
    if (content.includes(pattern)) {
      classification = 'partnership';
      confidence = 0.85;
      destination = 'owner';
      break;
    }
  }
}

// Check sales patterns
if (classification === 'unknown') {
  for (const pattern of salesPatterns) {
    if (content.includes(pattern)) {
      classification = 'sales_inquiry';
      confidence = 0.8;
      destination = 'sales_supervisor';
      break;
    }
  }
}

// Check support patterns
if (classification === 'unknown') {
  for (const pattern of supportPatterns) {
    if (content.includes(pattern)) {
      classification = 'support_request';
      confidence = 0.8;
      destination = 'zoho_desk';
      break;
    }
  }
}

// Check maintenance patterns
if (classification === 'unknown') {
  for (const pattern of maintenancePatterns) {
    if (content.includes(pattern)) {
      classification = 'maintenance_request';
      confidence = 0.75;
      destination = 'website_maintenance';
      break;
    }
  }
}

// Default to manual review
if (classification === 'unknown') {
  destination = 'owner';
  confidence = 0.3;
}

return {
  email_id: email.id,
  thread_id: email.threadId,
  from_email: fromEmail,
  from_name: fromName,
  subject: email.subject,
  snippet: email.snippet,
  classification: classification,
  confidence: confidence,
  destination: destination,
  timestamp: new Date().toISOString()
};

// Forward to Sales Supervisor
const email = $input.first().json;

return {
  ...email,
  action: 'forward_to_sales',
  status: 'routed',
  routed_to: 'Sales Supervisor',
  message: 'New prospect inquiry - forwarded to Sales Supervisor for follow-up'
};

// Route to Website Maintenance Agent
const email = $input.first().json;

return {
  ...email,
  action: 'maintenance_request',
  status: 'routed',
  routed_to: 'Website Maintenance Agent',
  message: 'Website maintenance request - forwarded to Website Maintenance Agent'
};

// Mark as processed and log
const email = $input.first().json;

return {
  ...email,
  status: 'processed',
  processed_at: new Date().toISOString()
};

// Return summary
const items = $input.all();

return {
  worker: 'email_router',
  status: 'completed',
  emails_processed: items.length,
  timestamp: new Date().toISOString()
};
